import ipaddress
import re

from frontdoor.config import values
from frontdoor.errors import ConfigError

_NETWORK = re.compile(r"[0-9A-Fa-f:.]+(?:/[0-9]+)?")


def parse_network(text: str):
    """A network in CIDR form, or a single address; None when it is neither."""
    if not _NETWORK.fullmatch(text):
        return None
    try:
        net = ipaddress.ip_network(text, strict=True)
    except ValueError:
        return None
    mapped = ipaddress.ip_network("::ffff:0.0.0.0/96")
    if net.version == 6 and net.prefixlen >= 96 and net.subnet_of(mapped):
        # An IPv4 address mapped into IPv6 is the IPv4 address.
        v4 = ipaddress.IPv4Address(int(net.network_address) & 0xFFFFFFFF)
        return ipaddress.ip_network((v4, net.prefixlen - 96), strict=True)
    return net


def networks(t: dict, key: str, what: str) -> tuple:
    if key not in t:
        return ()
    items = t[key]
    if not isinstance(items, list) or not all(isinstance(x, str) for x in items):
        raise ConfigError(f"{what}: {key} must be a list of networks")
    out = []
    for text in items:
        net = parse_network(text)
        if net is None:
            raise ConfigError(f"{what}: {text!r} is not a network")
        out.append(net)
    return tuple(out)


def parse(value) -> tuple:
    t = values.table(value, "clients")
    values.only_keys(t, ["trusted_proxies"], "clients")
    return networks(t, "trusted_proxies", "clients")
