"""Client addresses (docs/ratelimit.md, sections 6 and 7)."""

import ipaddress
import re

_V4 = re.compile(r"[0-9]{1,3}(?:\.[0-9]{1,3}){3}")
_PORT = re.compile(r"[0-9]{1,5}")
_V6_CHARS = re.compile(r"[0-9A-Fa-f:.]+")


def _normal(addr):
    if addr.version == 6 and addr.ipv4_mapped is not None:
        return addr.ipv4_mapped
    return addr


def parse_address(text: str):
    """An address with an optional port (section 7.3), or None when `text` is not one.

    An IPv4 address mapped into IPv6 is returned as the IPv4 address.
    """
    host = None
    if text.startswith("["):
        end = text.find("]")
        if end < 0:
            return None
        host, rest = text[1:end], text[end + 1:]
        if rest and not (rest.startswith(":") and _PORT.fullmatch(rest[1:]) and int(rest[1:]) <= 65535):
            return None
        if ":" not in host:
            return None
    elif text.count(":") == 1:
        host, port = text.split(":")
        if not _V4.fullmatch(host) or not _PORT.fullmatch(port) or int(port) > 65535:
            return None
    else:
        host = text
    if not _V6_CHARS.fullmatch(host):
        return None
    try:
        return _normal(ipaddress.ip_address(host))
    except ValueError:
        return None


def in_any(addr, nets) -> bool:
    return any(addr in n for n in nets)


def client_address(request, trusted):
    """The client address of a request (section 7): an address object, or the raw peer text when
    the peer is not an address at all."""
    peer = parse_address(request.peer.strip())
    if peer is None:
        return request.peer
    if not in_any(peer, trusted):
        return peer
    entries = []
    for value in request.headers.get_all("X-Forwarded-For"):
        entries.extend(e.strip(" \t") for e in value.split(","))
    if not entries:
        return peer
    before = peer
    for entry in reversed(entries):
        addr = parse_address(entry)
        if addr is None:
            return before
        if not in_any(addr, trusted):
            return addr
        before = addr
    return parse_address(entries[0])


def client_key(addr) -> str | None:
    """The key value of the `client` part (section 6)."""
    if isinstance(addr, str):
        return addr
    if addr.version == 4:
        return str(addr)
    return str(ipaddress.ip_network((addr, 64), strict=False))
