import math

from frontdoor.ratelimit.address import client_address, client_key, in_any
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"


class State:
    def __init__(self, limits, trusted):
        self.limits = limits
        self.trusted = trusted
        self.clock = None
        self.keys = [{} for _ in limits]
        self.limited = {lim.name: 0 for lim in limits}


def setup(config):
    return State(config.section("limit", None) or [], config.section("clients", ()) or ())


def _part(part, ctx, client):
    if part == "tenant":
        return ctx.tenant
    if part == "client":
        return client_key(client)
    if part == "route":
        return ctx.route.name
    if part == "method":
        return ctx.request.method
    value = ctx.request.headers.get(part[len("header:"):])
    if value is None:
        return None
    return value.strip(" \t") or None


def _covers(limit, ctx, client_cache):
    if limit.routes is not None and ctx.route.name not in limit.routes:
        return None
    if limit.methods is not None and ctx.request.method not in limit.methods:
        return None
    key = []
    for part in limit.key:
        value = _part(part, ctx, client_cache())
        if value is None:
            return None
        key.append(value)
    if limit.exempt:
        addr = client_cache()
        if not isinstance(addr, str) and in_any(addr, limit.exempt):
            return None
    return tuple(key)


def _seconds_up(ms) -> int:
    return math.ceil(ms / 1000)


def handle(ctx, state):
    if not state.limits:
        return None
    ts = ctx.request.ts_ms
    now = ts if state.clock is None else max(ts, state.clock)
    state.clock = now

    cache = []

    def client():
        if not cache:
            cache.append(client_address(ctx.request, state.trusted))
        return cache[0]

    covering = []  # (index, limit, bucket/window, cost)
    for i, limit in enumerate(state.limits):
        key = _covers(limit, ctx, client)
        if key is None:
            continue
        s = state.keys[i].get(key)
        if s is None:
            s = state.keys[i][key] = new_state(limit, now)
        s.refill(now)
        covering.append((limit, s, limit.cost_of(ctx.request.method)))
    if not covering:
        return None

    refusing = [(limit, s, cost) for limit, s, cost in covering if not s.allows(cost)]
    if not refusing:
        for _, s, cost in covering:
            s.charge(cost)
        limit, s, _ = min(covering, key=lambda c: c[1].remaining())  # min keeps the first of equals
        _headers(ctx, limit, s, now)
        return None

    for limit, _, _ in refusing:
        state.limited[limit.name] += 1
    best = None
    best_wait = None
    for limit, s, cost in refusing:
        wait = math.inf if s.exceeds(cost) else s.wait(cost, now)
        if best is None or wait > best_wait:
            best, best_wait = (limit, s), wait
    limit, s = best
    _headers(ctx, limit, s, now)
    if best_wait != math.inf:
        ctx.headers["Retry-After"] = str(max(1, _seconds_up(best_wait)))
    return 429


def _headers(ctx, limit, s, now):
    ctx.headers["RateLimit-Limit"] = str(limit.capacity)
    ctx.headers["RateLimit-Remaining"] = str(s.remaining())
    ctx.headers["RateLimit-Reset"] = str(s.reset(now))


def summary(state):
    if not state.limits:
        return {}
    return {"limited": dict(state.limited)}
"}

